const storage={get(k){try{return JSON.parse(localStorage.getItem(k)||'[]')}catch{return[]}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}}};let saved=new Set(storage.get('kyushu-saved-v1'));let exploreLimit=12,notebookLimit=12;let current='home',selectedDay=1,category='全部',region='全部區域',search='',onlyMarked=false,onlySaved=false;
