function header(k,t,p=''){return `<div class="pagehead"><div class="eyebrow">${k}</div><h1>${t}</h1>${p?`<p>${p}</p>`:''}</div>`}function footer(){return `<div class="sourcefooter">資料更新於 ${D.updated} · 來源：你的 Google Sheet · 此網頁為當次資料快照<br>地點資料以探索頁最近核對內容為準；班次、營業時間及訂位請以出發前店方公告確認。</div>`}
